    "source": "// Binary search on the answer: split a (all > 0) into at most k contiguous parts, minimise the largest part sum.\npub fn segments_needed(a: &[i64], cap: i64) -> i64 {\n    let mut cnt = 1;\n    let mut cur = 0;\n    for &x in a {\n        if cur + x > cap {\n            cnt += 1;\n            cur = x;\n        } else { cur += x; }\n    }\n    cnt\n}\n\n/// segments_needed for each cap in caps (every cap must be >= max(a)).\npub fn segments_list(a: &[i64], caps: &[i64]) -> Vec<i64> {\n    caps.iter().map(|&c| segments_needed(a, c)).collect()\n}\n\npub fn min_largest_sum(a: &[i64], k: i64) -> i64 {\n    let mut lo = *a.iter().max().unwrap();\n    let mut hi: i64 = a.iter().sum();\n    while lo < hi {\n        let mid = lo + (hi - lo) / 2;\n        if segments_needed(a, mid) <= k {\n            hi = mid;\n        } else {\n            lo = mid + 1;\n        }\n    }\n    lo\n}\n",
